<?= $this->layout('seller/layouts/main', ['meta' => $meta ?? ['title' => 'Gallery | Seller Area | LoLBoost.gg']]) ?>
<?php $images = $images ?? []; ?>
<div class="content container-fluid seller-gallery-page">
  <div class="sg-hero card mb-4"><div class="card-body p-4 p-lg-5"><div class="sg-hero-grid"><div><div class="sg-eyebrow"><i class="fa-duotone fa-images"></i> Seller Gallery</div><h1 class="sg-title">Gallery</h1><p class="sg-subtitle">Upload screenshots once, then use the image IDs in your Account API or Item API payloads.</p></div><div class="sg-info-card"><i class="fa-duotone fa-hashtag"></i><div><strong>Use image IDs</strong><span>Example: <code>"image_ids": [1, 2, 3]</code></span></div></div></div></div></div>
  <div class="card mb-4"><div class="card-header"><h5 class="card-header-title mb-0">Upload Images</h5></div><div class="card-body"><form id="seller-gallery-upload-form" action="<?= AJAX_URL ?>" method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="seller_gallery_upload"><div class="sg-upload-box"><div class="sg-upload-icon"><i class="fa-duotone fa-cloud-arrow-up"></i></div><div><h3>Drop screenshots here</h3><p>JPG, PNG, WEBP or GIF, max 8 MB each.</p></div><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple required></div><div class="mt-3 d-flex justify-content-end"><button class="btn btn-primary" type="submit"><i class="fa-regular fa-upload me-1"></i> Upload images</button></div></form></div></div>
  <div class="card mb-4"><div class="card-header"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><h5 class="card-header-title mb-0">Your Gallery</h5><span class="sg-count"><?= count($images) ?> images</span></div></div><div class="card-body"><?php if (empty($images)): ?><div class="sg-empty"><i class="fa-duotone fa-image"></i><h2>No images yet</h2><p>Upload your first screenshots and assign them to accounts using their image IDs.</p></div><?php else: ?><div class="sg-grid"><?php foreach ($images as $img): ?><div class="sg-card"><div class="sg-thumb"><img src="<?= esc($img['url'] ?? '') ?>" alt=""></div><div class="sg-body"><div class="sg-id">#<?= (int)($img['id'] ?? 0) ?></div><div class="sg-name" title="<?= esc($img['original_name'] ?? '') ?>"><?= esc($img['original_name'] ?? $img['filename'] ?? 'Image') ?></div><div class="sg-actions"><button type="button" class="btn btn-sm btn-outline-light sg-copy" data-copy="<?= (int)($img['id'] ?? 0) ?>"><i class="fa-regular fa-hashtag"></i> Copy ID</button><button type="button" class="btn btn-sm btn-outline-light sg-copy" data-copy="<?= esc($img['url'] ?? '') ?>"><i class="fa-regular fa-link"></i></button><form class="ajax-form d-inline" action="<?= AJAX_URL ?>" method="POST" onsubmit="return confirm('Delete this image?');"><input type="hidden" name="action" value="seller_gallery_delete"><input type="hidden" name="id" value="<?= (int)($img['id'] ?? 0) ?>"><button type="submit" class="btn btn-sm btn-outline-danger"><i class="fa-regular fa-trash-can"></i></button></form></div></div></div><?php endforeach; ?></div><?php endif; ?></div></div>
  <div class="card mb-4"><div class="card-header"><h5 class="card-header-title mb-0">API Usage</h5></div><div class="card-body"><div class="sg-code-title">Create account with gallery images</div><pre class="sg-code"><code>{
  "external_id": "seller-account-123",
  "title": "Diamond Account EUW",
  "game": "lol",
  "server": "EUW",
  "price": 4999,
  "status": "listed",
  "image_ids": [1, 2, 3]
}</code></pre><div class="form-text mt-2">You can also use <code>gallery_image_ids</code>. Both fields are accepted.</div></div></div>
</div>
<style>.seller-gallery-page{--sg-purple:#6d5cff;--sg-purple2:#b05cff;}.sg-hero{background:radial-gradient(circle at 12% 0%,rgba(109,92,255,.2),transparent 30%),radial-gradient(circle at 95% 100%,rgba(176,92,255,.12),transparent 28%),var(--bs-card-bg)!important}.sg-hero-grid{display:flex;align-items:center;justify-content:space-between;gap:24px}.sg-eyebrow{display:flex;align-items:center;gap:8px;color:#a78fff;font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.12em;margin-bottom:12px}.sg-title{font-size:clamp(1.8rem,4vw,2.6rem);line-height:1.1;margin:0 0 14px;font-weight:800}.sg-subtitle{font-size:1rem;color:rgba(255,255,255,.62);max-width:720px;margin:0}.sg-info-card{min-width:280px;display:flex;gap:14px;align-items:center;padding:18px;border-radius:14px;border:1px solid rgba(109,92,255,.28);background:linear-gradient(135deg,rgba(109,92,255,.16),rgba(255,255,255,.025))}.sg-info-card>i{width:44px;height:44px;border-radius:12px;background:rgba(109,92,255,.22);display:flex;align-items:center;justify-content:center;color:#c4b5fd;font-size:1.3rem;flex-shrink:0}.sg-info-card strong{display:block}.sg-info-card span{display:block;color:rgba(255,255,255,.55);font-size:.82rem;margin-top:3px}.sg-upload-box{position:relative;display:flex;align-items:center;gap:18px;border:1px dashed rgba(167,139,250,.45);border-radius:16px;background:rgba(109,92,255,.06);padding:26px;overflow:hidden}.sg-upload-box input[type=file]{position:absolute;inset:0;opacity:0;cursor:pointer}.sg-upload-icon{width:54px;height:54px;border-radius:16px;background:rgba(109,92,255,.18);display:flex;align-items:center;justify-content:center;color:#a78fff;font-size:1.65rem}.sg-upload-box h3{font-size:1.05rem;font-weight:800;margin:0 0 4px}.sg-upload-box p{margin:0;color:rgba(255,255,255,.55)}.sg-count{font-size:.78rem;font-weight:800;color:#a78fff;background:rgba(109,92,255,.14);border:1px solid rgba(109,92,255,.28);border-radius:999px;padding:4px 10px}.sg-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px}.sg-card{border:1px solid rgba(255,255,255,.08);border-radius:14px;overflow:hidden;background:rgba(255,255,255,.025)}.sg-thumb{height:135px;background:rgba(0,0,0,.25);display:flex;align-items:center;justify-content:center;overflow:hidden}.sg-thumb img{width:100%;height:100%;object-fit:cover}.sg-body{padding:12px}.sg-id{font-weight:900;color:#a78fff;font-size:1rem;margin-bottom:4px}.sg-name{color:rgba(255,255,255,.62);font-size:.82rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:12px}.sg-actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.sg-actions .btn{font-size:.74rem}.sg-empty{min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:rgba(255,255,255,.55)}.sg-empty i{font-size:2.5rem;color:rgba(255,255,255,.18);margin-bottom:16px}.sg-empty h2{color:#fff;font-size:1.25rem;font-weight:800;margin:0 0 8px}.sg-empty p{max-width:420px;margin:0}.sg-code-title{font-size:.78rem;font-weight:800;color:#a78fff;text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px}.sg-code{margin:0;background:rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:16px;color:#e2d9ff;white-space:pre-wrap;overflow:auto;font-size:.85rem}@media(max-width:768px){.sg-hero-grid{display:block}.sg-info-card{margin-top:22px;min-width:0}.sg-upload-box{align-items:flex-start}}</style>
<script>(function(){var form=document.getElementById('seller-gallery-upload-form');if(form){form.addEventListener('submit',function(e){e.preventDefault();var btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json();}).then(function(json){if(json.sendToast&&typeof create_toast==='function'){create_toast(json.sendToast.type,json.sendToast.title||'',json.sendToast.message||'');}if(json.refreshPage)window.location.reload();}).catch(function(){if(typeof create_toast==='function')create_toast('danger','Upload failed','Please try again.');}).finally(function(){if(btn)btn.disabled=false;});});}document.querySelectorAll('.sg-copy').forEach(function(btn){btn.addEventListener('click',function(){var v=btn.getAttribute('data-copy')||'';if(navigator.clipboard)navigator.clipboard.writeText(v);if(typeof create_toast==='function')create_toast('success','Copied',v);});});})();</script>
